<script setup lang="ts">
import {computed,ref} from 'vue'
import {useRouter} from 'vue-router'
import Panel from '../components/Panel.vue';import Workflow from '../components/Workflow.vue'
import {api,run,refresh,current,busy,notify,kindName,isProcessImage} from '../store'
const props=defineProps<{mode:'recognition'|'restoration'}>();const repair=computed(()=>props.mode==='restoration');const router=useRouter()
const strength=ref(2);const threshold=ref(0);const mirror=ref(false);const denoise=ref(true);const close=ref(true);const source=ref('');const activeResult=ref('')
const images=computed(()=>current.value?.artifacts.filter(isProcessImage)||[])
const results=computed(()=>images.value.filter(a=>a.kind!=='original'))
const result=computed(()=>results.value.find(a=>a.id===activeResult.value)||results.value.at(-1))
const original=computed(()=>images.value.find(a=>a.id===source.value)?.url||current.value?.original_url||'/assets/original.png')
async function process(){await run(async()=>{if(!current.value)throw new Error('请先上传印谱');let sourceId=source.value||null
 if(repair.value&&denoise.value){const cleaned=await api(`/seals/${current.value.id}/process`,{method:'POST',body:JSON.stringify({operation:'clean',strength:strength.value,threshold:threshold.value,source_artifact_id:sourceId})});sourceId=cleaned.id}
 const a=await api(`/seals/${current.value.id}/process`,{method:'POST',body:JSON.stringify({operation:repair.value&&close.value?'repair':'extract',strength:strength.value,threshold:threshold.value,mirror:mirror.value,source_artifact_id:sourceId})});activeResult.value=a.id;await refresh();notify('已生成真实OpenCV处理版本并归档。')})}
async function ai(){await run(async()=>{if(!current.value)throw new Error('请先上传印谱');const a=await api(`/seals/${current.value.id}/ai`,{method:'POST',body:JSON.stringify({task:props.mode,source_artifact_id:source.value||null})});activeResult.value=a.id;await refresh();notify('模型推理完成，请人工核对。')})}
async function accept(){if(result.value&&current.value)await run(async()=>{await api(`/seals/${current.value!.id}/records`,{method:'POST',body:JSON.stringify({kind:'review',artifact_id:result.value!.id,comment:'用户选择此版本进入三维设计'})});await refresh();notify('人工选择版本已归档。');router.push('/reconstruction')})}
</script>
<template><div class="processing-grid"><Panel :title="repair?'原始图像':'古印谱原图'" :note="repair?'保留原始古印痕迹':'图像与区域辨别'"><div class="process-image"><span class="image-tag">{{current?'当前图像 · 保留原稿':'原始扫描 · 参考素材'}}</span><img :src="original" alt="处理前原始图像"></div><div class="chips"><button class="chip" @click="process" :disabled="!current||busy">{{repair?'去噪与印文修复':'印文区域提取'}}</button><a class="chip" :href="original" target="_blank" rel="noopener">放大查看</a></div><label v-if="current" class="version-select">来源版本<select v-model="source" aria-label="处理来源版本"><option value="">原始扫描</option><option v-for="a in images.filter(a=>a.kind!=='original')" :value="a.id" :key="a.id">{{kindName[a.kind]}} · {{a.id.slice(0,8)}}</option></select></label></Panel>
<Panel :title="repair?'AI智能修复结果':'AI识别结果'" :note="result?'真实处理产物 · 待人工校订':'参考效果 · 尚未计算'"><div class="process-image result-image"><span class="image-tag">{{result?`${result.metadata.engine} · 实际结果`:'修复示意 · 非实际结果'}}</span><img :src="result?.url||'/assets/restored.png'" alt="处理结果或参考设计示意"></div><div class="actions"><button class="primary grow" @click="accept" :disabled="!result">确认{{repair?'修复':'提取'}}结果</button><button @click="activeResult=results.at(-2)?.id||''" :disabled="results.length<2">切换版本</button></div><p v-if="result" class="hint">来源 {{result.metadata.source_artifact_id?.slice(0,8)}} · 非AI：{{result.metadata.ai_inference===false?'是':'否'}} · 人工核验后使用</p></Panel>
<Panel :title="repair?'智能修复控制台':'印章属性分析'" note="参数可调 · 可溯源版本管理"><template v-if="repair"><label class="toggle-card"><span><b>纸张噪声剥离</b><small>去除微小连通区域，保留原始文件</small></span><input type="checkbox" v-model="denoise" aria-label="纸张噪声剥离"></label><label class="toggle-card"><span><b>笔画与边缘修复</b><small>用形态学闭运算连接相邻印迹</small></span><input type="checkbox" v-model="close" aria-label="笔画与边缘修复"></label><div class="toggle-card muted"><span><b>残缺区域重建</b><small>深度修复模型未接入</small></span><input type="checkbox" disabled aria-label="残缺区域重建未接入"></div><label class="toggle-card"><span><b>印面水平镜像</b><small>镜像参数将记录在处理版本中</small></span><input type="checkbox" v-model="mirror" aria-label="图像水平镜像"></label><label class="range-label">修复强度 <span>{{strength}} / 5</span><input type="range" min="1" max="5" v-model.number="strength" aria-label="修复强度"></label></template>
<template v-else><dl class="data-list"><div><dt>印章形制</dt><dd>待人工确认</dd></div><div><dt>印面类型</dt><dd>朱文 / 白文待校核</dd></div><div><dt>识别文字</dt><dd>识别模型未接入</dd></div><div><dt>字形风格</dt><dd>不自动推断</dd></div><div><dt>尺寸比例</dt><dd>原图坐标归一化</dd></div><div><dt>年代归属</dt><dd>须有文献证据</dd></div></dl><div class="notice"><h3>印文图像处理引擎</h3><p>可提取红色或黑色印迹，输出可供三维重建的印面图。此功能使用OpenCV，不识别古篆字含义。</p></div><label class="range-label">二值化阈值 <span>{{threshold||'自动Otsu'}}</span><input type="range" min="0" max="254" v-model.number="threshold" aria-label="二值化阈值"></label></template>
<button class="primary full" :disabled="!current||busy" @click="process">{{repair?'重新生成处理版本':'生成印文提取版本'}}</button><button class="full secondary-ai" :disabled="!current||busy" @click="ai">运行{{repair?'深度修复':'篆字识别'}}模型</button><p class="hint">模型未配置时会返回明确的不可用状态。</p></Panel></div><Panel class="workflow-panel" :title="repair?'修复前后与工作流程':'印文识别与处理进度'" note="真实处理 · 人工校核"><Workflow :active="repair?2:1"/></Panel></template>
